SALES={'total_sales':('Total sales','currency','Won opportunity line revenue'), 'win_rate':('Win rate','percent','Won opportunities / all opportunities'), 'conversion':('Value conversion','percent','Won amount / closed amount'), 'average_won_deal':('Average won deal','currency','Won amount / won opportunities'), 'won_cycle':('Won sales cycle','days','Average elapsed days, one value per won opportunity'), 'pipeline_generated':('Pipeline generated','currency','All opportunity line amounts'), 'open_opportunities':('Open opportunities','count','Opportunity stage does not contain Closed'), 'weighted_pipeline':('Weighted pipeline','currency','Open amount × probability / 100')}
SERVICE={'created_cases':('Created cases','count','Distinct case IDs'), 'closed_cases':('Closed cases','count','Non-null closed date'), 'close_days':('Average time to close','days','Average UTC calendar-day difference for closed cases'), 'open_cases':('Open cases','count','Null closed date'), 'missing_accounts':('Unassigned account','count','Cases with no linked account')}
FILTERS={'sales':['account','account_type','industry','type','owner','days_bucket','stage'], 'service':['priority','type','division','owner','industry','status','account']}
DIMENSIONS={'sales':['account_type','account','industry','family','product','owner','stage','month','days_bucket','close_date'], 'service':['owner','priority','type_division','week_origin','status','industry','origin']}
def catalog():
    return {'semantic_version':'1.0.0','dashboards':['sales','service'],'filters':FILTERS,'dimensions':DIMENSIONS,'metrics':{d:[{'id':k,'label':v[0],'unit':v[1],'definition':v[2],'grain':'opportunity' if d=='sales' else 'case','date_field':'close_date' if d=='sales' and k in ['total_sales','win_rate','conversion','average_won_deal','won_cycle'] else 'closed_date' if k in ['closed_cases','close_days'] else 'created_at'} for k,v in ms.items()] for d,ms in [('sales',SALES),('service',SERVICE)]}}
